<?php declare(strict_types='1'); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Text Sorter','description'=>'Sort text lines alphabetically in ascending or descending order.','url'=>'https://smarttoolz.in/tools/text-sorter/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Text Sorter</h1><p>Sort lines alphabetically.</p></section><section class="tool-workspace"><div class="tool-panel"><textarea id="i" rows="12" placeholder="One item per line..."></textarea><select id="d"><option value="1">A → Z</option><option value="-1">Z → A</option></select><button id="go" class="tool-btn">Sort Lines</button><textarea id="o" rows="12" readonly></textarea></div></section></main><script>go.onclick=()=>o.value=i.value.split(/\r?\n/).sort((a,b)=>a.localeCompare(b)*+d.value).join('\n')</script><?php smarttoolz_tool_page_end(); ?>